def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) == abs(dc):
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                length = abs(dr)
                segments.append((r1, c1, sr, sc, length))
                for k in range(length + 1):
                    out[r1 + sr * k][c1 + sc * k] = 1

    for r, c in sixes:
        for r1, c1, sr, sc, length in segments:
            # Is this six on the segment connecting the aligned ones?
            if (r - r1) * sc == (c - c1) * sr:
                k = (r - r1) * sr
                if 0 <= k <= length:
                    # Draw the perpendicular diagonal through this six.
                    if sr == sc:
                        # Original segment slopes +1; perpendicular has constant r+c.
                        for rr in range(h):
                            cc = r + c - rr
                            if 0 <= cc < w:
                                out[rr][cc] = 6
                    else:
                        # Original segment slopes -1; perpendicular has constant c-r.
                        for rr in range(h):
                            cc = c - r + rr
                            if 0 <= cc < w:
                                out[rr][cc] = 6
                    break

    # Preserve all original colored cells.
    for r, c in ones:
        out[r][c] = 1
    for r, c in sixes:
        out[r][c] = 6
    return out
